head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > mergeCellsFixedRows]<br/>Body 의 고정 Row 영역에서 동일한 값이 연속되는 Cell 을 자동으로 병합하는 방식을 설정합니다.",
    "validation" : [
        "'byrestriccol' 설정 시 왼쪽 Column 이 병합된 범위 내에서 'bycol' 방식으로 병합을 수행하며, 'bycol' 방식으로 병합되는 각 Cell 의 왼쪽 Cell 이 서로 다른 병합 그룹이라면 병합되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — byrestriccol(세로 제한) 전용. 상단 6행을 고정 Row 영역(fixedRow=6)으로 두고, 그 안에서 계층형 cascade 로 세로병합.
//  ★ mergeCellsFixedRows 는 fixedRow 영역(상단 N개 Row)에만 적용되고, 그 영역 안에서 byrestriccol(왼쪽 Column 병합 범위 내 세로병합)을 수행한다.
//  · col1 사업부  : 영업본부(0~2) / 관리본부(3~5)
//  · col2 팀      : 1팀(0~1) / 2팀(2) / 3팀(3~5)        (byrestriccol 제한 경계)
//  · col3 평가등급 : 우수(0~4) / 보통(5)
//        byrestriccol → 평가등급(우수)이 왼쪽 col2(팀) 경계로 제한 → 우수가 1팀[0~1]/2팀[2]/3팀[3~4] 로 잘게 세로병합 (왼쪽 그룹 다르면 미병합)
//  · col4 비고    : col3 과 동일값(우수/보통)
//  · 행0~5 = 고정 Row 영역(fixedRow=6) → 병합 대상.
//  · 행6 이하 = 비고정(스크롤) 영역 → 병합 제외. 전체 행 수(16)가 그리드 height 보다 커서 세로 스크롤이 발생하며,
//    세로 스크롤을 내려도 고정 Row 영역(행0~5, 병합된 부분)이 상단에 그대로 남아 '고정 Row' 임을 눈으로 인지할 수 있다.
scwin.MERGE_DATA = [
    { "col1": "영업본부", "col2": "1팀", "col3": "우수", "col4": "우수" },
    { "col1": "영업본부", "col2": "1팀", "col3": "우수", "col4": "우수" },
    { "col1": "영업본부", "col2": "2팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "보통", "col4": "보통" },
    { "col1": "전략본부", "col2": "4팀", "col3": "우수", "col4": "우수" },
    { "col1": "전략본부", "col2": "4팀", "col3": "우수", "col4": "우수" },
    { "col1": "전략본부", "col2": "4팀", "col3": "보통", "col4": "보통" },
    { "col1": "기획본부", "col2": "5팀", "col3": "우수", "col4": "우수" },
    { "col1": "기획본부", "col2": "5팀", "col3": "우수", "col4": "우수" },
    { "col1": "기획본부", "col2": "6팀", "col3": "보통", "col4": "보통" },
    { "col1": "지원본부", "col2": "7팀", "col3": "우수", "col4": "우수" },
    { "col1": "지원본부", "col2": "7팀", "col3": "보통", "col4": "보통" },
    { "col1": "감사본부", "col2": "8팀", "col3": "우수", "col4": "우수" },
    { "col1": "감사본부", "col2": "8팀", "col3": "보통", "col4": "보통" }
];



// comp 생성 : con_mergeCellsFixedRows 값으로 고정 Row 영역(fixedRow) 에 자동 병합을 적용한 그리드 1개를 동적 생성한다.
//  ★ mergeCellsFixedRows 는 생성 attribute 로 주지 않고, 데이터 적재 + 렌더가 끝난 뒤 mergeCellsFixedRows() 메소드로 적용한다.
//     (생성 attribute 로 초기 렌더 중 세로병합하면 병합된 Row 가 height 0 으로 collapse 되어 일부 Row 가 사라짐)
//  ★ 시연 행(병합 cascade)을 모두 fixedRow 고정 영역(상단 6행)에 두어야 mergeCellsFixedRows(고정 Row 영역 한정) 가 적용된다.
//  ★ 전체 행 수(16) > 그리드 height → 세로 스크롤 발생. 스크롤을 내려도 고정 Row 영역이 상단에 고정으로 남아 '고정 Row' 임을 인지시킨다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (Target 재생성 시 동일 id 재생성이 무시되지 않도록 먼저 제거)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // con_ 설정값 수집 : '' 미설정(메소드 미호출) / byrestriccol
    let vMerge = con_mergeCellsFixedRows.getValue();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let labelText = '';
    if (vMerge === 'byrestriccol') {
        labelText = 'mergeCellsFixedRows=byrestriccol / 고정6행(행0~5). 평가등급(우수)이 왼쪽 팀 경계로 제한되어 1팀[행0~1]/2팀[행2]/3팀[행3~4] 로 잘게 세로병합. 세로 스크롤을 내려도 고정 Row 영역(행0~5, 병합)이 상단에 그대로 남아 고정 Row 임을 인지할 수 있다 (행6 이하 비고정 영역은 병합 제외)';
    } else {
        labelText = 'mergeCellsFixedRows=(미설정) / 고정6행. 메소드 미호출. 자동 병합 없음. 세로 스크롤로 고정 Row 영역 인지';
    }
    $c.gcm.createLabel('label="' + labelText + '"', '', 'label1');

    // 계층형 DataList 생성 후 데이터 적재 (모드 무관 동일)
    let dlNS = $c.gcm.getNameSpace();
    let strDL = '';
    strDL += '<w2:dataList ' + dlNS + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDL += '<w2:columnInfo>';
    strDL += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDL += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDL += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDL += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDL += '</w2:columnInfo>';
    strDL += '<w2:data use="true"></w2:data>';
    strDL += '</w2:dataList>';
    $p.data.create(strDL);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin["dlt_bind"] = arrDC[arrDC.length - 1];
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // ★ 고정 Row 수는 모드 무관 공통 = 6 (시연 행 0~5 전부 고정 영역에 포함, 행6 이하는 비고정 스크롤 영역)
    let properties = {
        dataList: "data:" + dlt_bind.id,
        fixedRow: 6
    };
    let cList = $c.gcm.createCList(properties);

    // target 생성 (mergeCellsFixedRows 속성은 부여하지 않음 → 아래에서 메소드로 적용)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCellsFixedRows sample (고정 Row 영역 / 제한 병합)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="사업부"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="팀"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column3" value="평가등급"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 생성(데이터 적재 완료) 후 mergeCellsFixedRows() 메소드로 고정 Row 영역 병합 적용 (미설정이면 호출 안 함)
    if (vMerge !== '') {
        let grid = $p.getComponentById("target1");
        grid.mergeCellsFixedRows(vMerge);
    }
}



// 병합 상태 확인 : 고정 Row 영역 Body td 의 rowSpan / colSpan 을 읽어 병합 그룹을 직관 형식으로 출력하고,
//  제한(왼쪽 Cell 그룹 불일치)으로 미병합되는 경계를 명확히 출력한다.
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = target1.options.mergeCellsFixedRows || "never";
    bottom.setReturnValue("[옵션] mergeCellsFixedRows : " + mode);
    bottom.setReturnValue("[고정 Row 수] fixedRow : " + (target1.options.fixedRow || 0));

    // 표시되는(흡수되지 않은) 고정 영역 td 의 병합 그룹 수집
    let tds = document.querySelectorAll("td[id*='target1_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let descs = [];
    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === "none" || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        if (rs <= 1 && cs <= 1) continue;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        let val = (td.textContent || "").trim();
        if (rs > 1 && cs === 1) {
            descs.push("세로병합 col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] = '" + val + "'");
        } else if (cs > 1 && rs === 1) {
            descs.push("가로병합 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] = '" + val + "'");
        } else {
            descs.push("블록병합 [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] (" + rs + "x" + cs + ") = '" + val + "'");
        }
    }

    bottom.setReturnValue("병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }

    // 제한 경계 판정 : 평가등급(col3=index2)의 우수가 왼쪽 팀(col2) 경계로 제한되어 1팀[0~1]/2팀[2]/3팀[3~4] 로 나뉘는지 확인.
    if (mode === "byrestriccol") {
        // 우수가 행0(1팀 시작)·행2(2팀 시작)·행3(3팀 시작) 에서 각각 별도 그룹으로 시작(anchor) = 팀 경계로 끊김
        let split = scwin.isAnchor("target1", 2, 0) && scwin.isAnchor("target1", 2, 2) && scwin.isAnchor("target1", 2, 3);
        bottom.setReturnValue("[제한 경계] 평가등급(우수)이 같아도 왼쪽 팀 경계로 제한되어 1팀[행0~1]/2팀[행2]/3팀[행3~4] 로 나뉘어 세로병합 : " + split);
    }
}



// 공통 : colIndex 컬럼에서 row 행이 '병합 시작(anchor)' 인지 여부 (표시되는 td 가 존재하면 anchor = 별도 그룹 시작)
scwin.isAnchor = function (gid, colIndex, row) {
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_" + row + "_" + colIndex + "']");
    for (let i = 0; i < tds.length; i++) {
        if (getComputedStyle(tds[i]).display !== 'none' && tds[i].offsetParent !== null) return true;
    }
    return false;
}
